import {icon} from './ui.mjs';
const $=s=>document.querySelector(s);
// Screenshot benchmark values are preview data, not a live billing catalogue.
export const memberPlans=[
 {id:'free',name:'免费体验',price:0,features:['本地编辑与保存','自备材料文本比对','项目与成果管理'],available:true},
 {id:'standard',name:'基础会员',price:10,features:['规划：论文查重与 AI 率检测','规划：AI 写作与修改辅助','具体额度待确认'],available:false},
 {id:'advanced',name:'进阶会员',price:20,features:['规划：基础会员相关能力','规划：更高检测与研读额度','具体额度待确认'],available:false},
 {id:'pro',name:'尊享会员',price:40,features:['规划：进阶会员相关能力','规划：写作、PPT 与科研工具权益','具体额度待确认'],available:false}
];
export const serviceBundles=[
 {id:'rewrite',name:'查重与降重套餐',price:99,features:['论文查重 × 2','AI 率检测 × 2','修改建议 × 2','降重辅助 × 2']},
 {id:'reduce',name:'降 AI 率套餐',price:129,features:['论文查重 × 2','AI 率检测 × 2','修改建议 × 2','降 AI 率辅助 × 2']},
 {id:'dual',name:'降重与降 AI 率套餐',price:159,features:['论文查重 × 2','AI 率检测 × 2','修改建议 × 2','降重与降 AI 率辅助 × 2']}
];
export function purchaseSelection(plan,quantity=1,kind='member'){
 const selected=(kind==='bundle'?serviceBundles:memberPlans.filter(p=>!p.available)).find(p=>p.id===plan)||(kind==='bundle'?serviceBundles[0]:memberPlans[1]);
 const n=Number(quantity);return {plan:selected,quantity:Number.isInteger(n)&&n>=1&&n<=365?n:1,kind:kind==='bundle'?'bundle':'member',price:null,referencePrice:selected.price,paymentEnabled:false};
}
function navigation(tab){return `<nav class="commerce-tabs" aria-label="购买中心">${[['plans','购买会员'],['bundles','购买套餐'],['recharge','账户充值'],['redeem','兑换码']].map(([id,title])=>`<a href="#membership/${id}" ${tab===id?'aria-current="page"':''}>${title}</a>`).join('')}</nav>`;}
function heading(tab){return `<div class="hub-heading"><div><h1>会员与购买中心</h1><p>会员、专项套餐和账户充值，按你的研究需求选择。</p></div><a class="btn secondary" href="#membership">会员与用量 ${icon('arrow',16)}</a></div><section class="purchase-hero"><div><span>PAPERKNOW MEMBERSHIP</span><h2>为你的论文与研究，选择合适的支持</h2><p>当前为定价方案预览，支付与在线权益尚未开放。</p></div><div class="purchase-hero-icon">${icon('diamond',60)}</div></section>${navigation(tab)}`;}
function rules(){return `<div class="purchase-notice">${icon('shield',18)}<p>当前为 PaperKnow 定价方案预览。会员计价单位、有效期及详细额度待确认；套餐字数上限、有效期和写作套餐定价待确认。当前不会创建订单、扣款或开通会员，不承诺检测通过或分数下降。</p></div>`;}
function card(plan,kind){return `<article class="purchase-plan ${plan.id==='advanced'||plan.id==='reduce'?'featured':''}"><div class="purchase-plan-top"><span class="purchase-plan-icon">${icon(plan.available?'user':'diamond',25)}</span><span class="purchase-status">${plan.available?'当前可用':'定价预览'}</span></div><h3>${plan.name}</h3><div class="purchase-price"><b>${plan.available?'免费':'¥'+plan.price}</b><span>${plan.available?'本地体验':kind==='bundle'?'参考价 / 套':'参考价 · 计价单位待确认'}</span></div><ul>${plan.features.map(f=>`<li><span aria-hidden="true">✓</span>${f}</li>`).join('')}</ul>${plan.available?'<a class="btn secondary full" href="#home">继续免费体验</a>':`<a class="btn ${plan.id==='advanced'||plan.id==='reduce'?'primary':'secondary'} full" href="#membership/checkout?kind=${kind}&plan=${plan.id}&quantity=1">查看购买方案 ${icon('arrow',16)}</a>`}<small>${plan.available?'当前无需付费':'服务尚未接入，暂不收款'}</small></article>`;}
export function mountMemberPlans(){
 $('.dashboard').innerHTML=heading('plans')+`<div class="purchase-section-head"><div><h2>选择会员等级</h2><p>基础、进阶和尊享三级会员。计价单位与有效期将在开放前确认。</p></div></div><div class="purchase-plans commerce-member-plans">${memberPlans.map(p=>card(p,'member')).join('')}</div>`+rules()+`<section class="card purchase-comparison"><header><h2>会员权益对比</h2><span>具体额度待确认，在线服务未开放</span></header><div class="purchase-table-wrap"><table><thead><tr><th>功能与权益</th>${memberPlans.map(p=>`<th>${p.name}</th>`).join('')}</tr></thead><tbody>${[['本地保存与成果导出','可用','可用','可用','可用'],['论文查重 / AI 率检测','自备材料比对；AI 检测未接入','规划中 · 额度待确认','规划中 · 额度待确认','规划中 · 额度待确认'],['AI 写作、修改与润色','模板与手动编辑','规划中','规划中','规划中'],['文献研读、PPT 与科研工具','以当前工具能力为准','规划中','规划中','规划中'],['云存储 / 文档大小 / Token','未启用','待确认','待确认','待确认'],['有效期 / 重置 / 超额规则','本地体验不收费','待确认','待确认','待确认']].map(r=>`<tr>${r.map((v,i)=>i?`<td>${v}</td>`:`<th scope="row">${v}</th>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="card purchase-faq"><h2>购买前须知</h2><details open><summary>现在可以支付吗？</summary><p>当前仅为购买页面预览。微信与支付宝支付、正式账户和权益发放尚未接入。</p></details><details><summary>查重结果是否等同于学校检测？</summary><p>不等同于知网、万方或维普。PaperKnow 当前比对自备材料，未来开放学术检索的实际覆盖范围会单独说明。</p></details><details><summary>是否自动续费？可以退款或开票吗？</summary><p>当前不启用自动续费。退款、发票和有效期规则将在正式开放前提供。</p></details></section>`;
}
export function mountCommerce(tab){
 if(tab==='bundles'){$('.dashboard').innerHTML=heading(tab)+`<div class="purchase-section-head"><div><h2>查重与修改专项套餐</h2><p>按服务次数组合；检测版本、字数上限与有效期以正式方案为准。</p></div><span class="purchase-status">写作套餐价格待补充</span></div><div class="purchase-plans">${serviceBundles.map(p=>card(p,'bundle')).join('')}</div>`+rules();return;}
 if(tab==='recharge'){
 $('.dashboard').innerHTML=heading(tab)+`<section class="card purchase-detail commerce-form"><h2>账户充值</h2><p>在线余额尚未启用，充值服务未开放。</p><h3>选择充值额度</h3><div class="commerce-amounts">${[30,50,100].map(n=>`<button class="btn secondary" data-credit="${n}" aria-pressed="false">${n} 研究积分</button>`).join('')}</div><label for="credit-custom">其他数量</label><input id="credit-custom" type="number" min="1" max="100000" step="1" placeholder="输入正整数积分数量"><p id="credit-summary" role="status">请选择积分数量。积分与人民币兑换比例待确认。</p><div class="purchase-payment-options"><span>微信支付 · 待接入</span><span>支付宝 · 待接入</span></div><button class="btn primary" disabled>充值尚未开放</button><p class="member-caption">没有真实余额记录，不显示模拟余额，也不会发放积分。</p></section>`+rules();
 const input=$('#credit-custom');const show=()=>{const n=Number(input.value);$('#credit-summary').textContent=Number.isInteger(n)&&n>=1&&n<=100000?`已选 ${n} 研究积分。应付金额待兑换比例确认，当前无法充值。`:'请输入 1～100000 的整数积分数量。';document.querySelectorAll('[data-credit]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.credit)===n)));};document.querySelectorAll('[data-credit]').forEach(b=>b.onclick=()=>{input.value=b.dataset.credit;show();});input.oninput=show;return;
 }
 $('.dashboard').innerHTML=heading('redeem')+`<section class="card purchase-detail commerce-form"><h2>兑换码中心</h2><p>后续可用于兑换会员、专项套餐或研究积分，支持的类型以正式规则为准。</p><label for="member-code">兑换码</label><input id="member-code" type="text" maxlength="64" autocomplete="off" placeholder="输入兑换码"><button id="code-check" class="btn secondary">检查输入格式</button><p id="code-message" role="status">兑换服务尚未接入，输入内容不会被发送或保存。</p><button class="btn primary" disabled>兑换尚未开放</button><p class="member-caption">格式检查不代表兑换码真实有效。有效期、使用次数与适用权益需要服务端验证。</p></section>`+rules();$('#code-check').onclick=()=>{$('#code-message').textContent=/^[A-Za-z0-9-]{6,64}$/.test($('#member-code').value.trim())?'输入格式符合要求；兑换服务未开放，尚未验证有效性，也未发放权益。':'请使用 6～64 位字母、数字或连字符；实际格式以正式发放规则为准。';};
}
export function mountMemberCheckout(planId,quantity,kind){
 const s=purchaseSelection(planId,quantity,kind),p=s.plan;const back=s.kind==='bundle'?'bundles':'plans';
 $('.dashboard').innerHTML=`<div class="hub-heading"><div><h1>确认购买方案</h1><p>当前仅预览方案，支付尚未开放。</p></div><a class="btn secondary" href="#membership/${back}">重新选择套餐</a></div><div class="purchase-checkout-grid"><section class="card purchase-detail"><div class="purchase-detail-heading"><span class="purchase-plan-icon">${icon('diamond',28)}</span><h2>${p.name}</h2><span class="purchase-status">定价预览</span></div><dl class="purchase-summary"><div><dt>参考价格</dt><dd>¥${p.price}${s.kind==='bundle'?' / 套':' · 计价单位待确认'}</dd></div><div><dt>有效期、字数限制与额度规则</dt><dd>待确认</dd></div><div><dt>自动续费</dt><dd>不启用</dd></div></dl><label for="purchase-quantity">购买数量${s.kind==='member'?'（计价单位待确认）':'（套）'}</label><input id="purchase-quantity" type="number" min="1" max="365" step="1" value="${s.quantity}"><p id="quantity-error" role="status"></p><h3>方案内容（待开放）</h3><ul class="purchase-checkout-features">${p.features.map(f=>`<li>${icon('shield',16)}${f}</li>`).join('')}</ul><div class="purchase-payment-options"><span>微信支付 · 待接入</span><span>支付宝 · 待接入</span></div></section><aside class="card purchase-confirm"><span class="purchase-confirm-label">方案确认</span><h2>${p.name}</h2><dl><div><dt>选择数量</dt><dd id="selected-quantity">${s.quantity}</dd></div><div><dt>参考合计</dt><dd id="reference-total">¥${p.price*s.quantity}</dd></div><div><dt>实际应付</dt><dd>待正式规则确认</dd></div></dl><div class="purchase-payment-state">${icon('clock',20)}<div><b>支付尚未开放</b><p>参考合计不构成正式报价或订单。</p></div></div><button class="btn primary full" disabled>暂未开放支付</button><a class="btn secondary full" href="#home">继续免费体验</a><p class="purchase-confirm-note">当前未创建订单、未扣款、未开通会员。服务范围、退款与发票规则将在开放前确认。</p></aside></div>`+rules();
 $('#purchase-quantity').oninput=()=>{const n=Number($('#purchase-quantity').value);if(!Number.isInteger(n)||n<1||n>365){$('#quantity-error').textContent='请输入 1～365 的整数数量。';$('#reference-total').textContent='—';$('#selected-quantity').textContent='待修正';return;}window.history.replaceState(null,'',`#membership/checkout?kind=${s.kind}&plan=${p.id}&quantity=${n}`);$('#quantity-error').textContent='';$('#reference-total').textContent='¥'+n*p.price;$('#selected-quantity').textContent=String(n);};
}
